const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const models=[
  {id:'employee',number:'01',label:'WORKFORCE TENANT',name:'Employee',accent:'navy',persona:'Sofia Alvarez',portrait:'./assets/personas/sofia-alvarez.webp',relationship:'Works for Harborline',record:[['Directory relationship','Internal'],['Typical User type','Member'],['Authentication','Harborline-managed account'],['Lifecycle authority','HR and workforce processes'],['Resources','Microsoft 365 and internal applications']],admin:['Open the employee in Entra ID → Users.','Verify User type, identities, employee attributes and authentication methods.','Inspect groups, enterprise-app assignments, devices and lifecycle workflow history.'],experience:['Signs in with a Harborline workforce account.','Uses My Apps, Microsoft 365 and assigned internal applications.','Registers organization-approved authentication methods and uses managed devices where required.'],proof:'Hire or change event → member record → assignment → successful internal application access',href:'#sofia/1/live',cta:'Open Sofia’s workforce proof'},
  {id:'b2b',number:'02',label:'WORKFORCE TENANT · B2B',name:'External collaborator',accent:'violet',persona:'Tom Reilly',portrait:'./assets/personas/tom-reilly.webp',relationship:'Works with Harborline',record:[['Directory relationship','External'],['Typical User type','Guest'],['Authentication','Home identity or external provider'],['Lifecycle authority','Invitation, sponsor, package or review'],['Resources','Selected organizational applications']],admin:['Open the collaborator in the Harborline workforce tenant.','Verify User type, identities, invitation or redemption state, sponsor and home organization.','Inspect access package, group and enterprise-app assignments; correlate the resource-tenant sign-in.'],experience:['Accepts an invitation or completes workforce B2B self-service sign-up.','Authenticates with an identity they already own; Harborline does not need their password.','Enters selected Harborline organizational resources, often through an invitation link or My Apps.'],proof:'External identity → resource-tenant guest object → selected assignment → organizational resource',href:'#tom/1/live',cta:'Open Tom’s Workforce record'},
  {id:'customer',number:'03',label:'EXTERNAL TENANT',name:'Customer or partner',accent:'orange',persona:'Elena Petrova',portrait:'./assets/personas/elena-petrova.webp',relationship:'Uses a Harborline application',record:[['Directory relationship','Customer'],['Account surface','Customer account'],['Authentication','Configured customer sign-in method'],['Lifecycle authority','Application journey and business relationship'],['Resources','Branded customer or partner applications']],admin:['Switch to the External ID external tenant and open the customer record.','Inspect identities, collected attributes, authentication methods and sign-in activity.','Open the application’s user flow, app registration, roles and API authorization evidence.'],experience:['Starts inside a branded application such as Franchise Hub or Supplier Desk.','Signs up or signs in through the application’s configured customer user flow.','Returns directly to the application; its roles, claims and business data determine what appears.'],proof:'Branded application → customer user flow → token → application or API decision',href:'#elena-franchise/live',cta:'Open Elena’s External ID proof'}
];

function header(view){return `<header class="compare-header"><a href="#home" class="compare-brand"><img src="./assets/majorkey-logo-dark.svg" alt="MajorKey" width="180" height="31"><span></span><b>Identity model comparison</b></a><a href="#home" class="compare-home">All journeys</a></header><nav class="compare-tabs" aria-label="Choose a comparison view">${[['overview','At a glance'],['admin','Administrator view'],['user','User experience'],['decision','Choose the model']].map(([id,label],i)=>`<a href="#identity-models/${id}" ${view===id?'aria-current="page"':''}><b>0${i+1}</b>${label}</a>`).join('')}</nav>`;}
function person(model){return `<div class="compare-person"><img src="${esc(model.portrait)}" alt="Portrait of ${esc(model.persona)}"><span><small>${esc(model.relationship)}</small><strong>${esc(model.persona)}</strong></span></div>`;}
function recordCard(model){return `<article class="model-record ${model.accent}"><header><span>${model.number}</span><div><small>${esc(model.label)}</small><h2>${esc(model.name)}</h2></div></header>${person(model)}<dl>${model.record.map(([term,value])=>`<div><dt>${esc(term)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><div class="model-proof"><small>PROOF CHAIN</small><strong>${esc(model.proof)}</strong></div><a href="${model.href}">${esc(model.cta)} →</a></article>`;}
function overview(){return `<section class="compare-intro"><span>ONE ORGANIZATION · THREE RELATIONSHIPS</span><h1>They can all appear in Entra.<br><em>They are not the same identity model.</em></h1><p>Start with the business relationship. Then show the directory record, the authentication boundary and the application experience that follows.</p></section><aside class="compare-correction"><b>Keep the language clean</b><span>An employee is normally an internal member. B2B collaboration is for an external collaborator in the Workforce tenant. External ID customer accounts belong to an external tenant and support branded customer and partner applications.</span></aside><section class="model-records" aria-label="Identity model records">${models.map(recordCard).join('')}</section><section class="compare-storyline"><div><small>THE PRESENTER’S QUESTION</small><h2>What relationship are we governing?</h2></div><ol><li><b>Employee</b><span>Do they work for us and need organizational productivity resources?</span></li><li><b>B2B collaborator</b><span>Do they work with us and need selected resources in our Workforce tenant?</span></li><li><b>External customer</b><span>Do they use our application as a customer, franchisee, supplier or partner?</span></li></ol></section>`;}
function admin(){return `<section class="compare-intro compact"><span>ADMINISTRATOR VIEW</span><h1>Three records.<br><em>Three things to inspect.</em></h1><p>Use the same order on every side: relationship, account, authentication, assignment and evidence.</p></section><section class="admin-compare">${models.map(model=>`<article class="admin-model ${model.accent}"><header><span>${model.number}</span><div><small>${esc(model.label)}</small><h2>${esc(model.name)}</h2></div></header>${person(model)}<ol>${model.admin.map((step,i)=>`<li><b>0${i+1}</b><span>${esc(step)}</span></li>`).join('')}</ol><div class="admin-fields"><small>FIELDS TO SAY OUT LOUD</small>${model.record.slice(0,4).map(([term,value])=>`<span><b>${esc(term)}</b>${esc(value)}</span>`).join('')}</div><a class="compare-action" href="${model.href}">${esc(model.cta)} →</a></article>`).join('')}</section><div class="compare-warning"><b>Verify the actual record.</b><span>User type describes the user’s relationship to the tenant; it does not by itself prove how the person authenticates. Open Identities and the sign-in record before describing the account.</span></div>`;}
function user(){return `<section class="compare-intro compact"><span>PERSON EXPERIENCE</span><h1>Show where the person starts.<br><em>Then show where identity returns them.</em></h1><p>The clearest difference is the destination: organizational resources for Workforce identities, branded business applications for external customers.</p></section><section class="experience-compare">${models.map(model=>`<article class="experience-model ${model.accent}"><header>${person(model)}<span>${model.number}</span></header><div class="experience-door"><small>START HERE</small><strong>${model.id==='employee'?'Harborline sign-in or assigned application':model.id==='b2b'?'Invitation or shared organizational resource':'Franchise Hub, Supplier Desk or Integration Exchange'}</strong></div><ol>${model.experience.map((step,i)=>`<li><b>${i+1}</b><span>${esc(step)}</span></li>`).join('')}</ol><div class="experience-end"><small>LAND HERE</small><strong>${model.id==='employee'?'My Apps and internal work':model.id==='b2b'?'The selected Harborline resource':'The branded application experience'}</strong></div><a class="compare-action" href="${model.href}">${esc(model.cta)} →</a></article>`).join('')}</section><section class="compare-demo-script"><div><small>SHOW IT IN FIVE MINUTES</small><h2>One administrator screen. One person screen.</h2></div><ol><li><b>1</b>Open the user record and name the tenant.</li><li><b>2</b>Say who owns the credential.</li><li><b>3</b>Open the person’s real entry point.</li><li><b>4</b>Show the resulting application access.</li><li><b>5</b>Match the identity, app and time in the evidence.</li></ol></section>`;}
function decision(){const rows=[['Works for the organization','Employee','No','No'],['Uses Microsoft 365 or internal productivity resources','Employee','Often','Usually no'],['Uses their own identity to access selected organizational resources','No','B2B collaboration','No'],['Needs Teams, SharePoint or another Workforce resource','No','B2B collaboration','No'],['Signs up inside a customer, franchise or supplier application','No','No','External tenant'],['Needs branded sign-up and app-specific recovery','No','No','External tenant'],['Needs app or API roles tied to a business relationship','Possible','Possible','External tenant']];return `<section class="compare-intro compact"><span>CHOOSE THE MODEL</span><h1>Start with the resource.<br><em>Then place the identity.</em></h1><p>The person’s employer is useful context, but the resource and experience usually determine the right tenant model.</p></section><section class="decision-table" aria-label="Identity model decision guide"><div class="decision-row heading"><strong>Business requirement</strong><span>Employee</span><span>B2B collaboration</span><span>External tenant</span></div>${rows.map(row=>`<div class="decision-row"><strong>${esc(row[0])}</strong>${row.slice(1).map(value=>`<span class="${value==='No'?'no':''}">${esc(value)}</span>`).join('')}</div>`).join('')}</section><section class="decision-close"><div><small>HARBORLINE EXAMPLES</small><h2>Use the model, then follow the person.</h2></div><div><a href="#sofia/1/story"><b>Employee</b><span>Sofia joins Harborline →</span></a><a href="#tom/1/story"><b>B2B / Workforce collaborator</b><span>Tom’s organizational-resource identity →</span></a><a href="#elena-franchise/experience"><b>External customer</b><span>Elena enters Franchise Hub →</span></a></div></section>`;}
export function identityModelsPage(view='overview'){const safe=['overview','admin','user','decision'].includes(view)?view:'overview';const body=safe==='admin'?admin():safe==='user'?user():safe==='decision'?decision():overview();return `<div class="compare-shell">${header(safe)}<main class="compare-main">${body}<footer class="compare-footer"><span>MajorKey · Harborline identity model guide</span><a href="https://learn.microsoft.com/en-us/entra/external-id/" target="_blank" rel="noopener noreferrer">Microsoft Entra External ID documentation ↗</a></footer></main></div>`;}
